-- 0. ИСПРАВЛЕНИЕ СХЕМЫ (перенаправляем FK на правильную таблицу)
ALTER TABLE IF EXISTS public.equipment_models 
DROP CONSTRAINT IF EXISTS equipment_models_supplier_id_fkey;

ALTER TABLE public.equipment_models
