    -- 4. ВОССТАНОВЛЕНИЕ ХАРАКТЕРИСТИК ДЛЯ СУЩЕСТВУЮЩЕГО ОБОРУДОВАНИЯ
    -- Обновляем таблицу equipment, проставляя характеристики из только что созданных моделей
    UPDATE public.equipment e
    SET 
        specifications = em.specifications,
        type = em.specifications->>'type' -- Пытаемся взять тип из JSON, если он есть
    FROM public.equipment_models em
    WHERE LOWER(e.manufacturer) = LOWER(em.manufacturer) 
      AND LOWER(e.model) = LOWER(em.model)
      AND (e.specifications IS NULL OR e.specifications = '{}'::jsonb);

    RAISE NOTICE 'Характеристики оборудования обновлены на основе моделей.';

END $$;
